function eraseAll(s: string, part: string): string {
  const st: string[] = [];
  const m = part.length;
  for (const ch of s) {
    st.push(ch);
    if (st.length >= m && ch === part[m - 1]) {
      let match = true;
      for (let k = 0; k < m && match; k++) {
        if (st[st.length - m + k] !== part[k]) match = false;
      }
      if (match) st.length -= m;
    }
  }
  return st.join("");
}

